"use client";

import Image from "next/image";
import { useEffect, useState } from "react";
import Breadcrumb from "@/components/header/breadcrumb";
import getLocations from "@/services/locations";
import sendeQuestion from "@/services/askRepresentative";
import { inputCls, labelCls } from "@/components/profile-page/fieldStyles";

export default function DetailPage({ companyId }: { companyId: string }) {
  const [loading, setLoading] = useState(false);
  const [spinner, setSpinner] = useState(true);
  const [submitStatus, setSubmitStatus] = useState("");
  const [errorMessage, setErrorMessage] = useState("");

  const [data, setData] = useState({
    id: "",
    name: "",
    first_name: "",
    last_name: "",
    email: "",
    userrole: "",
    companyid: "",
    location: {
      id: 0,
      code: "",
      name: "",
      slug: "",
      type: "",
    },
    companyname: "",
    companytype: "",
    parent_location: {
      id: 0,
      code: "",
      name: "",
      slug: "",
      type: "",
    },
    users: [
      {
        id: 0,
        name: "",
        email: "",
        last_name: "",
        first_name: "",
      },
    ],
  });

  const [questionData, setQuestionData] = useState({
    firstName: "",
    lastName: "",
    phone: "",
    email: "",
    country: "",
    pax: "",
    subject: "",
    question: "",
    companyid: "",
    adminlocation: "",
    adminname: "",
    agencymail: "",
  });

  const sendSubmit = async () => {
    if (
      questionData.email &&
      questionData.firstName &&
      questionData.lastName &&
      questionData.question
    ) {
      setSubmitStatus("");
      setErrorMessage("");

      setLoading(true);

      try {
        await sendeQuestion({ requestData: questionData });
        setErrorMessage("");
        setSubmitStatus("success");
      } catch (err: any) {
        if (err && err.errors && typeof err.errors === "object") {
          setErrorMessage(err.errors[Object.keys(err.errors)[0]][0]);
        } else {
          setErrorMessage(err?.message || "There is a problem. Please try again later.");
        }
        setSubmitStatus("error");
      }

      setLoading(false);
    } else {
      setErrorMessage("Please fill in the required fields.");
      setSubmitStatus("error");
    }
  };

  const fetchLocations = async () => {
    await getLocations().then((res) => {
      setLocations(res);
    });
  };

  const fetchData = async () => {
    try {
      const response = await fetch(
        `/api/apiv2/representative/detail/${companyId}`
      );

      if (!response.ok) {
        throw new Error("Network response was not OK");
      }

      const data = await response.json();
      setData(data);
      setQuestionData({
        ...questionData,
        adminlocation: data.location.name,
        adminname: data.name,
        agencymail: data.email,
        companyid: data.companyid,
      });
    } catch (error) {}
    setSpinner(false);
  };

  const getLocation = (item: any) => {
    if (parseInt(item.id) === 12364) {
      return "Central Africa";
    }
    const result =
      (item.location.type === "city" ? item.parent_location.name + "/" : "") +
      item.location.name;

    return result !== null ? result : "";
  };

  const [locations, setLocations] = useState([
    { id: 0, name: "", phone_code: "" },
  ]);

  useEffect(() => {
    fetchData();
    fetchLocations();
  }, []);

  if (spinner)
    return (
      <div className="tw-flex tw-justify-center tw-py-40">
        <span className="tw-inline-block tw-h-16 tw-w-16 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#ece9f1] tw-border-t-[#854ec9]" />
      </div>
    );

  const req = <span className="tw-text-[#d6336c]">*</span>;

  return (
    <main>
      <div className="tw-mx-auto tw-max-w-screen-xl tw-px-4 tw-my-8">
        <Breadcrumb
          items={[
            {
              pageTitle: "Representative Agencies",
              pageUrl: "/representative",
            },
            {
              pageTitle: "Representative Detail",
              pageUrl: "",
            },
          ]}
        />

        {submitStatus == "error" && (
          <div
            className="tw-mb-4 tw-rounded-xl tw-border-0 tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-sm tw-font-medium tw-text-[#b3261e]"
            role="alert"
          >
            {errorMessage}
          </div>
        )}
        {submitStatus == "success" && (
          <div
            className="tw-mb-4 tw-rounded-xl tw-border-0 tw-bg-[#e8f7ee] tw-px-4 tw-py-3 tw-text-sm tw-font-medium tw-text-[#1a9c54]"
            role="alert"
          >
            Your information has been saved.
          </div>
        )}

        <div className="tw-mt-3 tw-grid tw-gap-6 md:tw-grid-cols-[3fr_9fr]">
          <div className="tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_10px_28px_rgba(20,16,28,0.05)]">
            <div className="tw-p-5">
              <div className="tw-text-center">
                <Image
                  src={`https://d2lpxiu1sq3srq.cloudfront.net/representative/${data.companyid}.jpeg`}
                  alt={data.name}
                  className="tw-mx-auto tw-h-auto tw-w-full tw-max-w-[200px] tw-rounded-xl"
                  width={250}
                  height={250}
                />
              </div>

              <h2 className="tw-font-display tw-mt-3 tw-text-center tw-text-lg tw-font-bold tw-text-[#14101c]">
                {data.name}
              </h2>
              <p className="tw-mt-1 tw-flex tw-items-center tw-justify-center tw-gap-1.5 tw-text-center tw-text-sm tw-text-[#5d556c]">
                <Image
                  src={
                    "/images/flags/4x3/" +
                    (data.location.type === "city"
                      ? data.parent_location?.code?.toLowerCase()
                      : data.location?.code?.toLowerCase()) +
                    ".svg"
                  }
                  alt=""
                  width={20}
                  height={20}
                />{" "}
                TravelShop Booking {getLocation(data)}
              </p>
              <ul className="tw-mt-4 tw-space-y-0 tw-p-0">
                {[
                  { k: "Number of reviews", v: "3" },
                  { k: "Response rate", v: "10%" },
                  { k: "Age Range", v: "2-99" },
                  { k: "Rating", v: "4.2" },
                  { k: "Response time", v: "within 1 day" },
                ].map((row) => (
                  <li
                    key={row.k}
                    className="tw-flex tw-items-center tw-justify-between tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1] tw-py-2.5 tw-text-sm tw-text-[#5d556c] last:tw-border-0"
                  >
                    {row.k}:{" "}
                    <strong className="tw-text-[#14101c]">{row.v}</strong>
                  </li>
                ))}
              </ul>
            </div>
          </div>

          <div className="tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_10px_28px_rgba(20,16,28,0.05)]">
            <div className="tw-p-6 md:tw-p-7">
              <h2 className="tw-font-display tw-mb-5 tw-text-xl tw-font-bold tw-text-[#14101c]">
                Send a Question
              </h2>

              <div className="tw-grid tw-gap-x-6 tw-gap-y-5 md:tw-grid-cols-2">
                <div>
                  <label htmlFor="questionFirstName" className={labelCls}>
                    First Name {req}
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="questionFirstName"
                    value={questionData.firstName}
                    onChange={(event: any) => {
                      setQuestionData({
                        ...questionData,
                        firstName: event.target.value,
                      });
                    }}
                  />
                </div>
                <div>
                  <label htmlFor="questionLastName" className={labelCls}>
                    Last Name {req}
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="questionLastName"
                    value={questionData.lastName}
                    onChange={(event: any) => {
                      setQuestionData({
                        ...questionData,
                        lastName: event.target.value,
                      });
                    }}
                  />
                </div>
                <div>
                  <label htmlFor="questionPhone" className={labelCls}>
                    Phone
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="questionPhone"
                    value={questionData.phone}
                    onChange={(event: any) => {
                      setQuestionData({
                        ...questionData,
                        phone: event.target.value,
                      });
                    }}
                  />
                </div>
                <div>
                  <label htmlFor="questionEmail" className={labelCls}>
                    Email Address {req}
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="questionEmail"
                    value={questionData.email}
                    onChange={(event: any) => {
                      setQuestionData({
                        ...questionData,
                        email: event.target.value,
                      });
                    }}
                  />
                </div>
                <div>
                  <label htmlFor="questionQountry" className={labelCls}>
                    Country
                  </label>
                  <select
                    className={inputCls}
                    id="questionQountry"
                    defaultValue={questionData.country}
                    onChange={(e) => {
                      setQuestionData({
                        ...questionData,
                        country: e.target.value,
                      });
                    }}
                  >
                    <option></option>
                    {locations
                      .sort(function (a, b) {
                        if (a.name < b.name) {
                          return -1;
                        }
                        if (a.name > b.name) {
                          return 1;
                        }
                        return 0;
                      })
                      .map((item: any) => (
                        <option key={item.id} value={item.id}>
                          {item.name}
                        </option>
                      ))}
                  </select>
                </div>
                <div>
                  <label htmlFor="questionPax" className={labelCls}>
                    Pax
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="questionPax"
                    value={questionData.pax}
                    onChange={(event: any) => {
                      setQuestionData({
                        ...questionData,
                        pax: event.target.value,
                      });
                    }}
                  />
                </div>
                <div className="md:tw-col-span-2">
                  <label htmlFor="questionSubject" className={labelCls}>
                    Subject
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="questionSubject"
                    value={questionData.subject}
                    onChange={(event: any) => {
                      setQuestionData({
                        ...questionData,
                        subject: event.target.value,
                      });
                    }}
                  />
                </div>
                <div className="md:tw-col-span-2">
                  <label htmlFor="questionMessage" className={labelCls}>
                    Your Question {req}
                  </label>
                  <textarea
                    className={`${inputCls} tw-min-h-[120px] tw-resize-y`}
                    id="questionMessage"
                    value={questionData.question}
                    onChange={(event: any) => {
                      setQuestionData({
                        ...questionData,
                        question: event.target.value,
                      });
                    }}
                  ></textarea>
                </div>
              </div>

              <button
                type="button"
                className="tw-mt-6 tw-flex tw-cursor-pointer tw-items-center tw-justify-center tw-gap-2 tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-10 tw-py-3 tw-text-sm tw-font-semibold tw-text-white tw-transition hover:tw-bg-[#6a3da4] disabled:tw-cursor-not-allowed disabled:tw-opacity-70"
                disabled={loading}
                onClick={sendSubmit}
              >
                {loading && (
                  <span className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent" />
                )}
                {loading ? "Loading..." : "Submit Question"}
              </button>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
