import { apiClient } from "@/lib/apiClient";

// apiv3 B2C: POST /representatives/contact — temsilci/şirket detayından enquiry lead.
// Tarayıcıdan çağrılır → apiClient /api/apiv3 proxy'sine gider (X-App-Token sunucuda eklenir).
// 422 doğrulama hatasında apiClient ApiError fırlatır (çağıran try/catch ile yakalar).
export default async function sendeQuestion({ requestData }: { requestData: any }) {
  const body: any = {
    companyid: requestData.companyid,
    first_name: requestData.firstName,
    last_name: requestData.lastName,
    email: requestData.email,
    message: requestData.question,
    subject: requestData.subject,
  };

  if (requestData.pax) {
    body.no_of_adults = Number(requestData.pax);
  }

  if (requestData.country || requestData.phone) {
    body.details = {
      location_id: requestData.country ? Number(requestData.country) : undefined,
      phone: requestData.phone || undefined,
      fullphone: requestData.phone || undefined,
    };
  }

  return apiClient("/representatives/contact", {
    method: "POST",
    body,
  });
}
